        resolve(true);
      } else {
        console.error('[API] Background removal failed with code:', code);
        console.error('[API] stderr:', stderr);
        resolve(false);
      }
    });

    python.on('error', (err) => {
      console.error('[API] Failed to spawn background removal process:', err);
      resolve(false);
    });
  });
}

